/** @internal Velocities are signed pixels/ms. Only meaningful speed changes deform the thumb. */
export function scrollImpulse(
  previousVelocity: number,
  velocity: number,
  elapsed: number,
) {
  const acceleration =
    (Math.abs(velocity) - Math.abs(previousVelocity)) / Math.max(16, elapsed);
  if (Math.abs(acceleration) < 0.035) return null;
  const amount = Math.min(0.04, Math.abs(acceleration) * 0.3);
  const stretching = acceleration > 0;
  const direction = Math.sign(velocity || previousVelocity);
  return {
    scaleY: 1 + (stretching ? amount : -amount),
    scaleX: 1 + (stretching ? -amount / 2 : amount / 2),
    origin: (stretching ? direction > 0 : direction < 0)
      ? "center top"
      : "center bottom",
  };
}

/** @internal Wheel/trackpad pressure at an edge compresses toward that edge. */
export function overscrollImpulse(
  position: number,
  maximum: number,
  delta: number,
) {
  if (maximum <= 0 || Math.abs(delta) < 4) return null;
  const top = position <= 0 && delta < 0;
  const bottom = position >= maximum - 1 && delta > 0;
  if (!top && !bottom) return null;
  const amount = Math.min(0.06, (Math.abs(delta) / 120) * 0.06);
  return {
    scaleY: 1 - amount,
    scaleX: 1 + amount / 2,
    origin: top ? "center top" : "center bottom",
  };
}

import { ScrollArea as BaseScrollArea } from "@base-ui/react/scroll-area";
import { animate, type JSAnimation } from "animejs";
import { forwardRef, useEffect, useRef, type HTMLAttributes } from "react";
import { cn } from "@/lib/cn";
import { readMotion, useReducedMotion } from "@/lib/motion";
import { themedEase, themedSpring } from "@/lib/motion-spring";
import { overscrollImpulse, scrollImpulse } from "./scroll-motion.js";
import { Screen, Surface, type SurfaceProps } from "./surface.js";

/** Native scrolling with a plastic thumb responding to changes in scroll speed.
 * The ref and native props address the viewport; className sizes the frame.
 */
export const ScrollArea = forwardRef<
  HTMLDivElement,
  HTMLAttributes<HTMLDivElement> & {
    surface?: boolean;
    surfaceSize?: SurfaceProps["size"];
    surfaceDepth?: SurfaceProps["depth"];
    /** Use the shared theme-aware display material on the fixed viewport. */
    screen?: boolean;
  }
>(function ScrollArea(
  {
    children,
    className,
    surface = false,
    surfaceSize,
    surfaceDepth,
    screen = false,
    ...props
  },
  ref,
) {
  const root = useRef<HTMLDivElement>(null);
  const thumbSurface = useRef<HTMLSpanElement>(null);
  const reduced = useReducedMotion();
  useEffect(() => {
    const frame = root.current;
    const viewport = frame?.querySelector<HTMLDivElement>(
      ".caps-scroll-viewport",
    );
    if (!viewport || !frame) return;
    let motion: JSAnimation | null = null;
    let idle: ReturnType<typeof setTimeout> | undefined;
    let position = viewport.scrollTop;
    let time = performance.now();
    let velocity = 0;
    const deform = (impulse: ReturnType<typeof scrollImpulse>) => {
      const thumb = thumbSurface.current;
      if (!impulse || reduced || !thumb) return;
      motion?.cancel();
      thumb.style.transformOrigin = impulse.origin;
      const feel = readMotion(thumb);
      const kick = themedEase(feel, { ease: "outQuad", duration: 45 });
      const settle = themedSpring(feel, { bounce: 0.18, duration: 180 });
      motion = animate(thumb, {
        scaleY: [
          { to: impulse.scaleY, ...kick },
          { to: 1, ...settle },
        ],
        scaleX: [
          { to: impulse.scaleX, ...kick },
          { to: 1, ...settle },
        ],
      });
    };
    const react = (nextVelocity: number, elapsed: number) => {
      const impulse = scrollImpulse(velocity, nextVelocity, elapsed);
      velocity = nextVelocity;
      deform(impulse);
    };
    const onWheel = (event: WheelEvent) => {
      if (event.ctrlKey || Math.abs(event.deltaX) > Math.abs(event.deltaY))
        return;
      const unit =
        event.deltaMode === 1
          ? 16
          : event.deltaMode === 2
            ? viewport.clientHeight
            : 1;
      const impulse = overscrollImpulse(
        viewport.scrollTop,
        viewport.scrollHeight - viewport.clientHeight,
        event.deltaY * unit,
      );
      if (!impulse) return;
      clearTimeout(idle);
      velocity = 0;
      deform(impulse);
    };
    const onScroll = () => {
      const now = performance.now();
      const gap = now - time;
      const elapsed = gap > 100 ? 16 : Math.max(16, gap);
      const delta = viewport.scrollTop - position;
      if (gap > 100) velocity = 0;
      react(delta / elapsed, elapsed);
      position = viewport.scrollTop;
      time = now;
      clearTimeout(idle);
      idle = setTimeout(() => {
        react(0, 32);
      }, 64);
    };
    viewport.addEventListener("scroll", onScroll, { passive: true });
    frame.addEventListener("wheel", onWheel, { passive: true });
    return () => {
      clearTimeout(idle);
      motion?.cancel();
      // A preference change re-runs this effect: never strand a squash.
      if (thumbSurface.current) thumbSurface.current.style.transform = "none";
      viewport.removeEventListener("scroll", onScroll);
      frame.removeEventListener("wheel", onWheel);
    };
  }, [screen, surface, reduced]);
  const viewport = (
    <BaseScrollArea.Viewport
      render={screen ? <Screen /> : <div />}
      {...props}
      ref={ref}
      className="caps-scroll-viewport"
    >
      <BaseScrollArea.Content style={{ minWidth: 0 }}>
        {children}
      </BaseScrollArea.Content>
    </BaseScrollArea.Viewport>
  );
  return (
    <BaseScrollArea.Root
      render={
        surface ? (
          <Surface
            size={surfaceSize ?? "md"}
            depth={surfaceDepth ?? "shallow"}
          />
        ) : (
          <div />
        )
      }
      ref={root}
      className={cn("caps-scroll-area", className)}
    >
      {screen ? (
        <div className="caps-display-gasket caps-scroll-display">
          {viewport}
        </div>
      ) : (
        viewport
      )}
      <Surface
        size="sm"
        depth="deep"
        placement="embedded"
        className="caps-scroll-track-surface"
      >
        <BaseScrollArea.Scrollbar className="caps-scroll-track">
          <BaseScrollArea.Thumb className="caps-scroll-thumb">
            <span className="caps-scroll-thumb-surface" ref={thumbSurface} />
          </BaseScrollArea.Thumb>
        </BaseScrollArea.Scrollbar>
      </Surface>
    </BaseScrollArea.Root>
  );
});

import { forwardRef, type HTMLAttributes, type ReactNode } from "react";
import { cn } from "@/lib/cn";

/** Native surface attributes with independent rim, depth and placement choices. */
export type SurfaceProps = HTMLAttributes<HTMLDivElement> & {
  /** Rim scale, independent of the content's dimensions. */
  size?: "sm" | "md" | "lg";
  depth?: "shallow" | "deep";
  /** Embedded surfaces borrow their parent's casing; omit the exterior surround. */
  placement?: "standalone" | "embedded";
};

/** A themeable frame around a surface. No padding or interaction ownership. */
export const Surface = forwardRef<HTMLDivElement, SurfaceProps>(
  function Surface(
    {
      className,
      size = "md",
      depth = "shallow",
      placement = "standalone",
      ...props
    },
    ref,
  ) {
    return (
      <div
        {...props}
        ref={ref}
        data-surface-size={size}
        data-surface-depth={depth}
        data-surface-placement={placement}
        className={cn("caps-surface", className)}
      />
    );
  },
);

/** Display face using theme surfaces while preserving the inherited text font. */
export const Screen = forwardRef<
  HTMLDivElement,
  HTMLAttributes<HTMLDivElement>
>(function Screen({ className, ...props }, ref) {
  return <div {...props} ref={ref} className={cn("caps-screen", className)} />;
});

/** A recessed display with a separate gasket and screen face. */
export type DisplayProps = SurfaceProps & {
  /** Fill a flex region rather than sizing to its content. */
  fit?: "content" | "fill";
  /** Reduce the gasket footprint for compact displays. */
  density?: "normal" | "compact";
};

/** Theme-owned recessed screen with a gasket and optional compact fill geometry. */
export const Display = forwardRef<HTMLDivElement, DisplayProps>(
  function Display(
    {
      children,
      className,
      depth = "deep",
      fit = "content",
      density = "normal",
      ...props
    },
    ref,
  ) {
    const fill = fit === "fill";
    return (
      <Surface
        {...props}
        className={cn(className, fill && "flex min-h-0 flex-1")}
        depth={depth}
        ref={ref}
      >
        <div
          className={cn(
            "caps-display-gasket",
            fill && "flex min-h-0 min-w-0 flex-1",
          )}
          data-display-density={density}
        >
          <Screen
            className={cn(
              fill && "flex min-h-0 min-w-0 flex-1 overflow-hidden",
            )}
          >
            {children}
          </Screen>
        </div>
      </Surface>
    );
  },
);

/** Props accepted by ScreenHeader. */
export type ScreenHeaderProps = {
  /** A decorative Sigil or App icon before the title. */
  icon?: ReactNode;
  title: ReactNode;
  /** A Status or short readout opposite the title. */
  status?: ReactNode;
} & Omit<HTMLAttributes<HTMLElement>, "title" | "children">;

/** A screen's title bar, printed on the glass above a hairline. */
export const ScreenHeader = forwardRef<HTMLElement, ScreenHeaderProps>(
  function ScreenHeader({ className, icon, status, title, ...props }, ref) {
    return (
      <header
        {...props}
        className={cn("caps-screen-header", className)}
        ref={ref}
      >
        {icon ? (
          <span className="caps-screen-header-icon" aria-hidden="true">
            {icon}
          </span>
        ) : null}
        <span className="caps-screen-header-title">{title}</span>
        {status ? (
          <span className="caps-screen-header-status">{status}</span>
        ) : null}
      </header>
    );
  },
);

/**
 * An instrument's cells: a grid of hairline-ruled cells that reflows to one
 * column when narrow. Put ScreenCells straight inside a Screen or Display.
 */
export const ScreenCells = forwardRef<
  HTMLDivElement,
  HTMLAttributes<HTMLDivElement> & {
    /** Compact instruments retain full-width rows instead of a cell grid. */
    appearance?: "default" | "compact";
  }
>(function ScreenCells({ appearance, className, ...props }, ref) {
  return (
    <div
      {...props}
      className={cn("caps-screen-cells", className)}
      data-appearance={appearance === "compact" ? appearance : undefined}
      ref={ref}
    />
  );
});

/** Props accepted by ScreenCell. */
export type ScreenCellProps = {
  /** Compact rows put their subject icon and legend before the controls. */
  appearance?: "default" | "compact";
  /** A leading subject icon. */
  icon?: ReactNode;
  /** The cell's tiny mono legend, such as "Processes". */
  legend?: ReactNode;
  /** A short value readout in the cell's corner, such as "2/4 ON". */
  readout?: ReactNode;
  /** Span the full row instead of one column. */
  wide?: boolean;
} & HTMLAttributes<HTMLDivElement>;

/** One instrument cell: a legend, an optional corner readout and its content. */
export const ScreenCell = forwardRef<HTMLDivElement, ScreenCellProps>(
  function ScreenCell(
    {
      children,
      className,
      legend,
      readout,
      icon,
      appearance,
      wide = false,
      ...props
    },
    ref,
  ) {
    return (
      <div
        {...props}
        className={cn("caps-screen-cell", className)}
        data-wide={wide || undefined}
        data-appearance={appearance === "compact" ? appearance : undefined}
        ref={ref}
      >
        {icon ? <span className="caps-screen-cell-icon">{icon}</span> : null}
        {legend ? (
          <span className="caps-screen-cell-legend">{legend}</span>
        ) : null}
        {readout ? (
          <span className="caps-screen-cell-readout">{readout}</span>
        ) : null}
        {appearance === "compact" ? (
          <div className="caps-screen-cell-controls">{children}</div>
        ) : (
          children
        )}
      </div>
    );
  },
);

import { STIPE_SPACING_NAMES } from "@fungi.computer/stipe";
import { cva } from "class-variance-authority";
import { createCn } from "cn/config";

/** A conditional class value accepted by cn. */
export type { ClassValue } from "cn";
export { cva };

/** Merge conditional classes with Tailwind rules and Stipe's named spacing. */
export const cn = createCn({
  extend: { theme: { spacing: [...STIPE_SPACING_NAMES] } },
});

/** Resolve a typed React class-name prop before merging its classes. */
export function resolveClassName<State>(
  className: string | ((state: State) => string | undefined) | undefined,
  state: State,
): string | undefined {
  return typeof className === "function" ? className(state) : className;
}

import {
  useLayoutEffect,
  useState,
  useSyncExternalStore,
  type RefObject,
} from "react";

/** Resolved, element-scoped motion. Times are milliseconds and distances pixels. */
export type Motion = Readonly<{
  reduced: boolean;
  squish: number;
  fast: number;
  normal: number;
  slow: number;
  springDuration: number;
  bounce: number;
  stretch: number;
  distance: number;
  stagger: number;
  blur: number;
  shake: number;
  steps: number;
  fuse: number;
  pressDepth: number;
  pressScale: number;
  ease: string;
  easeExit: string;
}>;

const defaults: Motion = Object.freeze({
  reduced: false,
  squish: 90,
  fast: 120,
  normal: 180,
  slow: 280,
  springDuration: 320,
  bounce: 0.3,
  stretch: 0.28,
  distance: 4,
  stagger: 24,
  blur: 0,
  shake: 3,
  steps: 0,
  fuse: 1,
  pressDepth: 0.5,
  pressScale: 1,
  ease: "cubic-bezier(0.2, 0, 0, 1)",
  easeExit: "cubic-bezier(0.4, 0, 1, 1)",
});

const preference = "(prefers-reduced-motion: reduce)";

/** Read at an event boundary; no root-theme lookup, so nested tokens win. */
export function readMotion(element: Element): Motion {
  const view = element.ownerDocument.defaultView;
  if (!view) return defaults;
  const style = view.getComputedStyle(element);
  const number = (name: string, fallback: number) => {
    const value = style.getPropertyValue(name).trim();
    const parsed = Number.parseFloat(value);
    return Number.isFinite(parsed) ? Math.max(0, parsed) : fallback;
  };
  const time = (name: string, fallback: number) => {
    const value = style.getPropertyValue(name).trim();
    return (
      number(name, fallback) *
      (value.endsWith("s") && !value.endsWith("ms") ? 1000 : 1)
    );
  };
  const browser: Partial<Pick<Window, "matchMedia">> = view;
  const reduced = browser.matchMedia?.(preference).matches ?? false;
  const duration = (name: string, fallback: number) =>
    reduced ? 120 : time(`--stipe-motion-${name}`, fallback);
  const amount = (name: string, fallback: number) =>
    reduced ? 0 : number(`--stipe-motion-${name}`, fallback);
  return {
    reduced,
    squish: duration("squish", defaults.squish),
    fast: duration("fast", defaults.fast),
    normal: duration("normal", defaults.normal),
    slow: duration("slow", defaults.slow),
    springDuration: duration("spring-duration", defaults.springDuration),
    bounce: Math.min(1, amount("bounce", defaults.bounce)),
    stretch: amount("stretch", defaults.stretch),
    distance: amount("distance", defaults.distance),
    stagger: reduced ? 0 : time("--stipe-motion-stagger", defaults.stagger),
    blur: amount("blur", defaults.blur),
    shake: amount("shake", defaults.shake),
    steps: Math.floor(amount("steps", defaults.steps)),
    fuse: number("--stipe-motion-fuse", defaults.fuse),
    pressDepth: reduced
      ? 0
      : number("--stipe-press-depth", defaults.pressDepth),
    pressScale: reduced
      ? 1
      : number("--stipe-press-scale", defaults.pressScale),
    ease: style.getPropertyValue("--stipe-motion-ease").trim() || defaults.ease,
    easeExit:
      style.getPropertyValue("--stipe-motion-ease-exit").trim() ||
      defaults.easeExit,
  };
}

/** Live motion tokens for a mounted ref, including nested theme and OS changes. */
export function useMotion(ref: RefObject<Element | null>): Motion {
  const [motion, setMotion] = useState<Motion>(() => ({
    ...defaults,
    reduced: true,
  }));
  useLayoutEffect(() => {
    const element = ref.current;
    const view = element?.ownerDocument.defaultView;
    if (!element || !view) return;
    const update = () => {
      const next = readMotion(element);
      setMotion((previous) =>
        JSON.stringify(previous) === JSON.stringify(next) ? previous : next,
      );
    };
    update();
    const observer = new view.MutationObserver(update);
    // Observe ancestors only: animation writes to descendants must not trigger reads.
    for (
      let parent: Element | null = element;
      parent;
      parent = parent.parentElement
    ) {
      observer.observe(parent, {
        attributes: true,
        attributeFilter: ["data-theme", "class", "style"],
      });
    }
    const browser: Partial<Pick<Window, "matchMedia">> = view;
    const media = browser.matchMedia?.(preference);
    media?.addEventListener("change", update);
    return () => {
      observer.disconnect();
      media?.removeEventListener("change", update);
    };
  }, [ref]);
  return motion;
}

/** Today's feel: the defaults that components' authored timings are written against. */
export const motionDefaults: Motion = defaults;

/**
 * Scale one of a component's authored durations by the theme's tempo
 * (`--stipe-motion-normal` against its 180ms default). Today's themes return
 * the authored value unchanged; reduced motion returns 0 (nothing travels).
 */
export function motionTime(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  return Math.round((authored * motion.normal) / defaults.normal);
}

/**
 * Scale one of a component's authored spring bounces by the theme's bounce
 * (`--stipe-motion-bounce` against its 0.3 default), so a lively control stays
 * livelier than a calm one inside every theme. A 0 theme is critically damped.
 */
export function motionBounce(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  const scaled = (authored * motion.bounce) / defaults.bounce;
  return Math.min(0.9, Math.max(0, scaled));
}

/** Scale an authored spring settle time by `--stipe-motion-spring-duration`. */
export function motionSpringTime(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  return Math.round(
    (authored * motion.springDuration) / defaults.springDuration,
  );
}

/** A CSS easing for a Web Animation, stepped when the theme asks for it. */
export function motionEasing(motion: Motion, ease: string): string {
  return motion.steps > 0 ? `steps(${String(motion.steps)}, end)` : ease;
}

/** Whether the element can run Web Animations (not in jsdom or old engines). */
export function canAnimate(element: Element): boolean {
  return "animate" in element;
}

const globalWindow: Partial<Pick<Window, "matchMedia">> = globalThis;

function prefersReducedMotion(): boolean {
  return globalWindow.matchMedia?.(preference).matches ?? false;
}

function subscribeReducedMotion(update: () => void) {
  const media = globalWindow.matchMedia?.(preference);
  media?.addEventListener("change", update);
  return () => {
    media?.removeEventListener("change", update);
  };
}

/** Server renders assume reduced motion, so hydration never starts mid-move. */
function serverReducedMotion() {
  return true;
}

/**
 * The live reduced-motion preference alone, for controls that only need to
 * know whether to move (their timing comes from `readMotion` when they do).
 */
export function useReducedMotion(): boolean {
  return useSyncExternalStore(
    subscribeReducedMotion,
    prefersReducedMotion,
    serverReducedMotion,
  );
}

import { spring, steps, type EasingParam } from "animejs";

import {
  motionBounce,
  motionSpringTime,
  motionTime,
  type Motion,
} from "./motion.js";

/** Anime.js timing for one tween or segment. */
export type MotionTiming = Readonly<{ ease: EasingParam; duration: number }>;

/** Timing for a change that must land at once. */
export const immediateTiming: MotionTiming = Object.freeze({
  ease: "linear",
  duration: 0,
});

/** A component's own spring, as authored for today's default feel. */
export type AuthoredSpring = Readonly<{ bounce: number; duration: number }>;

/**
 * Anime.js timing for an authored spring, in the theme's feel: bounce and
 * settle time scale with `--stipe-motion-bounce` and
 * `--stipe-motion-spring-duration`, and a stepped theme moves in
 * `--stipe-motion-steps` discrete steps instead. Today's themes reproduce the
 * authored spring exactly.
 */
export function themedSpring(
  motion: Motion,
  authored: AuthoredSpring,
): MotionTiming {
  const duration = motionSpringTime(motion, authored.duration);
  if (duration <= 0) return immediateTiming;
  if (motion.steps > 0) return { ease: steps(motion.steps), duration };
  return {
    ease: spring({ bounce: motionBounce(motion, authored.bounce), duration }),
    duration,
  };
}

/**
 * Anime.js timing for an authored eased segment: the duration scales with the
 * theme's tempo, and a stepped theme replaces the curve with steps.
 */
export function themedEase(
  motion: Motion,
  authored: MotionTiming,
): MotionTiming {
  const duration = motionTime(motion, authored.duration);
  return {
    ease: motion.steps > 0 ? steps(motion.steps) : authored.ease,
    duration,
  };
}

.caps-surface.--caps-surface-molding-base:
color-mix(
      in oklab,
      var(--color-base-100),
      var(--color-base-200) calc(var(--depth) * 100%)
    )

.caps-surface.--caps-surface-molding:
linear-gradient(
      155deg,
      color-mix(
        in oklab,
        var(--caps-surface-molding-base),
        var(--color-base-content)
          calc(var(--depth) * var(--stipe-surface-molding-contrast))
      ),
      var(--caps-surface-molding-base) 50%,
      color-mix(
        in oklab,
        var(--caps-surface-molding-base),
        white calc(var(--depth) * var(--stipe-surface-molding-contrast))
      )
    )

.caps-surface.border:
var(--caps-surface-rim) solid
      color-mix(
        in oklab,
        transparent,
        var(--stipe-linework) calc((1 - var(--depth)) * 100%)
      )

.caps-surface.background:
linear-gradient(
          var(--caps-surface-face, var(--color-base-100)),
          var(--caps-surface-face, var(--color-base-100))
        )
        padding-box,
      var(--stipe-surface-frame-image, var(--caps-surface-molding)) border-box

.caps-surface.boxShadow:
var(
      --stipe-shadow-raised,
      0 0 0 calc(var(--depth) * 1px)
        color-mix(
          in oklab,
          var(--color-base-content) 12%,
          var(--color-base-200)
        ),
      0 0 0 calc(var(--depth) * 3px) var(--color-base-200),
      0 calc(var(--depth) * 1px) 0 calc(var(--depth) * 4px)
        oklch(100% 0 0 / calc(var(--depth) * 0.3))
    )

.caps-display-gasket.boxShadow:
var(
      --stipe-shadow-inset,
      inset 0 calc(var(--depth) * 1px) calc(var(--depth) * 2px)
        color-mix(
          in oklab,
          var(--color-base-content) calc(var(--depth) * 20%),
          transparent
        )
    )

.caps-screen.boxShadow:
var(
      --stipe-shadow-inset,
      inset 0 calc(var(--depth) * 1px) calc(var(--depth) * 2px)
        color-mix(
          in oklab,
          var(--color-base-content) calc(var(--depth) * 12%),
          transparent
        )
    )
